MAP
    NAME "SS_MAP_DREN_COLECTORES_PLUVIALES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_colectores_pluviales.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_COLECTORES_DIAM"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from colepluv using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        TYPE line
        MINSCALE 1
        MAXSCALE 30000
        LABELITEM "diametro"
        CLASS
            NAME "colectores pluviales y flujo"
            STYLE
                SYMBOL 0
                COLOR 0 140 255
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                SIZE 19
                COLOR 0 140 255
            END #LABEL
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_COLECTORES_FLUJO"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from colepluv using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        STATUS DEFAULT
        TYPE LINE
        MINSCALE 1
        MAXSCALE 15000
        CLASS
             NAME "Flujo"
            STYLE
                COLOR 0 140 255
                SYMBOL "flechas"
                SIZE 10
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP